    def sql = new StringBuilder()
    def params = []
    sql << 'WITH months AS (\n'
    sql << '  SELECT CAST(date_trunc(\'month\', (SELECT a.as_of FROM dash_demo.as_of a)) - to_months(CAST(x.i AS INTEGER)) AS DATE) AS month\n'
    sql << '  FROM generate_series(0, 32) AS x(i)\n'
    sql << ')\n'
    sql << 'SELECT strftime(m.month, \'%Y-%m\') AS month,\n'
    sql << '       count(*) AS headcount\n'
    sql << 'FROM months m\n'
    sql << 'JOIN dash_demo.employees e\n'
    sql << '  ON e.hire_date <= m.month + to_months(1) - to_days(1)\n'
    sql << ' AND (e.termination_date IS NULL OR e.termination_date > m.month + to_months(1) - to_days(1))\n'
    sql << 'JOIN dash_demo.departments d ON d.department_id = e.department_id\n'
    sql << 'JOIN dash_demo.geo_cities g ON g.city_id = e.city_id\n'
    sql << 'WHERE true\n'
    if (hasDepartment) {
        sql << '  AND d.name = ?\n'
        params << asDeclaredType('department', 'String', department)
    } else {
        sql << '  AND 1=1\n'   // no value: this filter is off
    }
    if (hasCountry) {
        sql << '  AND g.country = ?\n'
        params << asDeclaredType('country', 'String', country)
    } else {
        sql << '  AND 1=1\n'   // no value: this filter is off
    }
    sql << 'GROUP BY m.month\n'
    sql << 'ORDER BY m.month\n'
    def data = params.isEmpty() ? dbSql.rows(sql.toString()) : dbSql.rows(sql.toString(), params)
    ctx.reportData('chart_dd18-chart-headcount-over-time', data)
