// ─── Widget: chart_dd18-chart-attrition-by-department (type=chart, dataSource=sql) ───
if (!componentId || componentId == 'chart_dd18-chart-attrition-by-department') {
    def sql = new StringBuilder()
    def params = []
    sql << 'WITH scope AS (\n'
    sql << '  SELECT e.department_id AS department_id,\n'
    sql << '         d.name AS department,\n'
    sql << '         e.hire_date AS hire_date,\n'
    sql << '         e.termination_date AS termination_date\n'
    sql << '  FROM dash_demo.employees e\n'
    sql << '  JOIN dash_demo.departments d ON d.department_id = e.department_id\n'
    sql << '  JOIN dash_demo.geo_cities g ON g.city_id = e.city_id\n'
    sql << '  WHERE true\n'
    if (hasDepartment) {
        sql << '    AND d.name = ?\n'
        params << asDeclaredType('department', 'String', department)
    } else {
        sql << '    AND 1=1\n'   // no value: this filter is off
    }
    if (hasCountry) {
        sql << '    AND g.country = ?\n'
        params << asDeclaredType('country', 'String', country)
    } else {
        sql << '    AND 1=1\n'   // no value: this filter is off
    }
    sql << '),\n'
    sql << 'grouped AS (\n'
    sql << '  SELECT CASE WHEN (SELECT count(*) FROM dash_demo.employees e2\n'
    sql << '                    WHERE e2.department_id = s.department_id\n'
    sql << '                      AND e2.termination_date IS NOT NULL) >= 8\n'
    sql << '              THEN s.department ELSE \'Other departments\' END AS department,\n'
    sql << '         s.hire_date AS hire_date,\n'
    sql << '         s.termination_date AS termination_date\n'
    sql << '  FROM scope s\n'
    sql << '),\n'
    sql << 'months AS (\n'
    sql << '  SELECT CAST(date_trunc(\'month\', (SELECT a.as_of FROM dash_demo.as_of a)) - to_months(CAST(x.i AS INTEGER)) AS DATE) AS month\n'
    sql << '  FROM generate_series(0, 32) AS x(i)\n'
    sql << '),\n'
    sql << 'heads AS (\n'
    sql << '  SELECT gr.department AS department, m.month AS month, count(*) AS heads\n'
    sql << '  FROM months m\n'
    sql << '  JOIN grouped gr\n'
    sql << '    ON gr.hire_date <= m.month + to_months(1) - to_days(1)\n'
    sql << '   AND (gr.termination_date IS NULL OR gr.termination_date > m.month + to_months(1) - to_days(1))\n'
    sql << '  GROUP BY gr.department, m.month\n'
    sql << '),\n'
    sql << 'average_heads AS (\n'
    sql << '  SELECT department, avg(heads) AS avg_heads FROM heads GROUP BY department\n'
    sql << '),\n'
    sql << 'leavers AS (\n'
    sql << '  SELECT department, count(*) AS leavers\n'
    sql << '  FROM grouped\n'
    sql << '  WHERE termination_date >= CAST(date_trunc(\'month\', (SELECT a.as_of FROM dash_demo.as_of a)) - to_months(32) AS DATE)\n'
    sql << '    AND termination_date <= (SELECT a.as_of FROM dash_demo.as_of a)\n'
    sql << '  GROUP BY department\n'
    sql << ')\n'
    sql << 'SELECT a.department || \' (\' || coalesce(l.leavers, 0) || \')\' AS department,\n'
    sql << '       round(100.0 * coalesce(l.leavers, 0) / a.avg_heads * 12.0 / 33.0, 2) AS attrition_pct\n'
    sql << 'FROM average_heads a\n'
    sql << 'LEFT JOIN leavers l ON l.department = a.department\n'
    sql << 'ORDER BY attrition_pct DESC\n'
    def data = params.isEmpty() ? dbSql.rows(sql.toString()) : dbSql.rows(sql.toString(), params)
    ctx.reportData('chart_dd18-chart-attrition-by-department', data)
}

